package org.jarvisassistant.app;

import android.Manifest;
import android.animation.ValueAnimator;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import com.google.android.gms.wearable.*;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** A watch-sized conversation surface. Opening the app never starts its microphone. */
public final class WatchActivity extends Activity implements MessageClient.OnMessageReceivedListener {
    private final Handler main=new Handler(Looper.getMainLooper());
    private Button followup;private TextView link;private volatile WatchRpc probe;private final java.util.concurrent.ExecutorService connectionWorker=java.util.concurrent.Executors.newSingleThreadExecutor();private boolean visible;private int connectionEpoch;private long checked;
    private TextView state,answer;private Button talk;private Orb orb;private boolean quiet;private String pending="";private Intent microphoneIntent;private final Map<String,String> requests=new HashMap<>();
    private final Runnable refresh=new Runnable(){public void run(){String text=pending.isEmpty()?WatchVoiceService.status:pending;if(!text.contentEquals(state.getText()))state.setText(text);String reply=WatchVoiceService.reply;if(!reply.contentEquals(answer.getText()))answer.setText(reply);answer.setVisibility(reply.isEmpty()?View.GONE:View.VISIBLE);String talkLabel=WatchVoiceService.running?"Stop listening":"Talk to JARVIS";if(!talkLabel.contentEquals(talk.getText())){talk.setText(talkLabel);talk.setContentDescription(talkLabel);}orb.state(WatchVoiceService.running,WatchVoiceService.status);if(followup!=null)followup.setVisibility(!WatchVoiceService.actionRequest.isEmpty()&&SystemClock.elapsedRealtime()<WatchVoiceService.actionUntil?View.VISIBLE:View.GONE);if(link!=null&&link.isAttachedToWindow()&&!WatchVoiceService.running&&probe==null&&SystemClock.elapsedRealtime()-checked>15000)checkConnection();main.postDelayed(this,350);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);getWindow().setNavigationBarColor(WatchStyle.BACKGROUND);getWindow().setStatusBarColor(WatchStyle.BACKGROUND);quiet=getPreferences(MODE_PRIVATE).getBoolean("quiet",false);home();}
    private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
    private LinearLayout page(String title){return WatchStyle.page(this,title);}
    private TextView text(String value,int size,int color){return WatchStyle.text(this,value,size,color);}
    private Button button(LinearLayout parent,String label,boolean primary,Runnable action){return WatchStyle.addButton(parent,label,primary,action);}
    private void home(){
        LinearLayout body=page("JARVIS");orb=new Orb(this);LinearLayout.LayoutParams orbSize=new LinearLayout.LayoutParams(dp(100),dp(42));orbSize.topMargin=dp(6);body.addView(orb,orbSize);
        state=text("Ready when you are",12,WatchStyle.MUTED);state.setPadding(0,dp(5),0,dp(2));state.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(state);
        talk=button(body,WatchVoiceService.running?"Stop listening":"Talk to JARVIS",true,()->{if(WatchVoiceService.running)stop();else listen(false,0);});
        answer=text(WatchVoiceService.reply,15,WatchStyle.TEXT);answer.setPadding(dp(12),dp(14),dp(12),dp(14));answer.setBackground(WatchStyle.background(this,WatchStyle.SURFACE,18));LinearLayout.LayoutParams answerSize=new LinearLayout.LayoutParams(-1,-2);answerSize.topMargin=dp(12);body.addView(answer,answerSize);answer.setVisibility(WatchVoiceService.reply.isEmpty()?View.GONE:View.VISIBLE);
        followup=button(body,"Continue on phone",true,()->command("continue"));followup.setVisibility(View.GONE);
        link=text("Checking connection…",11,WatchStyle.MUTED);link.setPadding(dp(4),dp(12),dp(4),dp(4));body.addView(link,new LinearLayout.LayoutParams(-1,-2));checked=0;
        tiles(body);button(body,quiet?"Spoken replies · off":"Spoken replies · on",false,()->{quiet=!quiet;getPreferences(MODE_PRIVATE).edit().putBoolean("quiet",quiet).apply();home();});button(body,"App updates",false,()->startActivity(new Intent(this,AppUpdatesActivity.class)));
    }
    private void tiles(LinearLayout body){String[] names={"Files","Codex","Laptop","Voice"},tools={"files","coding","remote","voice"};for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(this);body.addView(line,new LinearLayout.LayoutParams(-1,-2));for(int column=0;column<2;column++){int i=row*2+column;Button tile=button(line,names[i],false,()->{if(tools[i].equals("voice"))settings();else tool(tools[i]);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(column==0?0:4),dp(7),dp(column==0?4:0),0);tile.setLayoutParams(lp);}}}
    private void checkConnection(){if(!visible||probe!=null)return;checked=SystemClock.elapsedRealtime();int epoch=connectionEpoch;connectionWorker.execute(()->{try(WatchRpc client=new WatchRpc(this)){probe=client;JSONObject result=client.json("status",new JSONObject());main.post(()->{if(visible&&connectionEpoch==epoch&&link!=null)link.setText(result.optBoolean("available")?"Phone connected · "+result.optString("name","Laptop"):"Phone connected · Windows unavailable");});}catch(Exception error){main.post(()->{if(visible&&connectionEpoch==epoch&&link!=null)link.setText(error.getMessage()==null?"Open JARVIS on your phone to check the connection.":error.getMessage());});}finally{probe=null;}});}
    private void tool(String name){startActivity(new Intent(this,WatchToolsActivity.class).putExtra("tool",name));}
    private void settings(){LinearLayout body=page("Voice");body.addView(text("Wake listening starts off. Choose how long to keep the microphone listening for JARVIS.",13,WatchStyle.MUTED));button(body,quiet?"Spoken replies · off":"Spoken replies · on",false,()->{quiet=!quiet;getPreferences(MODE_PRIVATE).edit().putBoolean("quiet",quiet).apply();settings();});button(body,"Listen for 15 minutes",true,()->listen(true,15));button(body,"Listen for 1 hour",false,()->listen(true,60));button(body,"Listen until I stop",false,()->new AlertDialog.Builder(this).setMessage("Keep the watch microphone on until you stop it? Battery use will increase. It will not restart after a reboot or app stop.").setNegativeButton("Cancel",null).setPositiveButton("Start",(d,w)->listen(true,0)).show());body.addView(text("Longer listening uses more battery. Your paired connection has no timer.",12,WatchStyle.MUTED));button(body,"Stop listening",false,this::stop);button(body,"Back",false,this::home);}
    private void controls(){LinearLayout body=page("YOUR LAPTOP");body.addView(text("Media needs a 15-minute fingerprint approval on your phone. Lock and unlock are completed there too.",13,0xffa6babd));String[] names={"Play / pause","Previous track","Next track","Volume +","Volume −","Mute","Stop media control","Lock / unlock on phone","Coding sessions on phone"};String[] actions={"play-pause","previous","next","volume-up","volume-down","mute","media-stop","computer","coding"};for(int i=0;i<names.length;i++){String action=actions[i];button(body,names[i],i==0,()->command(action));}state=text("",13,0xff79e5d0);body.addView(state);button(body,"Back",false,this::home);}
    private void listen(boolean background,int minutes){microphoneIntent=new Intent(this,WatchVoiceService.class).putExtra("background",background).putExtra("minutes",minutes).putExtra("quiet",quiet);if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},91);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},91);return;}startMicrophone();}
    private void startMicrophone(){if(microphoneIntent==null)return;try{startForegroundService(microphoneIntent);pending="";home();}catch(RuntimeException e){pending="Could not start the microphone. Reopen JARVIS and try again.";}microphoneIntent=null;}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(grants.length==0||grants[0]!=PackageManager.PERMISSION_GRANTED){pending="Allow microphone and notifications to start listening.";microphoneIntent=null;return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},91);return;}startMicrophone();}
    private void stop(){WatchVoiceService.status="Listening off";stopService(new Intent(this,WatchVoiceService.class));pending="";home();}
    private void command(String action){if(!requests.isEmpty()){pending="Waiting for your phone. No button was sent again.";return;}pending="Contacting your phone…";WatchConnection.phone(this,node->{String id=UUID.randomUUID().toString();requests.put(id,node);try{byte[] bytes=new JSONObject().put("id",id).put("time",System.currentTimeMillis()).put("action",action).put("requestId",action.equals("continue")?WatchVoiceService.actionRequest:"").toString().getBytes(StandardCharsets.UTF_8);Wearable.getMessageClient(this).sendMessage(node,WatchWire.COMMAND,bytes).addOnFailureListener(e->{requests.remove(id);pending="Connection interrupted. No action was resent.";});main.postDelayed(()->{if(requests.remove(id)!=null)pending="No reply. Enable Galaxy Watch in the phone app. Check before trying a control again.";},15000);}catch(Exception e){requests.remove(id);pending="Request unavailable.";}},error->pending=error);}
    @Override public void onMessageReceived(MessageEvent event){if(!WatchWire.STATUS.equals(event.getPath())||event.getData().length>2048)return;try{JSONObject message=new JSONObject(new String(event.getData(),StandardCharsets.UTF_8));String id=message.optString("id");if(event.getSourceNodeId().equals(requests.get(id))){requests.remove(id);pending=message.optString("text");}}catch(Exception ignored){}}
    @Override protected void onResume(){super.onResume();visible=true;WatchConnection.phone(this,node->{try{connectionWorker.execute(()->WatchIdentity.announce(this,node));}catch(java.util.concurrent.RejectedExecutionException ignored){}},error->{});Wearable.getMessageClient(this).addListener(this);main.removeCallbacks(refresh);refresh.run();}
    @Override protected void onPause(){visible=false;connectionEpoch++;if(probe!=null)probe.close();main.removeCallbacks(refresh);Wearable.getMessageClient(this).removeListener(this);super.onPause();}
    @Override protected void onDestroy(){connectionWorker.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
    private static final class Orb extends View {
        boolean active,shown;String phase="";float time;ValueAnimator animator;final Paint paint=new Paint(3);
        Orb(Context c){super(c);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
        void state(boolean next,String label){boolean changed=active!=next||!phase.equals(label);active=next;phase=label;if(changed){motion();invalidate();}}
        private void motion(){boolean animate=active&&shown&&isAttachedToWindow()&&ValueAnimator.areAnimatorsEnabled();if(!animate){if(animator!=null){animator.cancel();animator=null;}return;}if(animator!=null)return;animator=ValueAnimator.ofFloat(0,(float)(Math.PI*2));animator.setDuration(1500);animator.setRepeatCount(-1);animator.setInterpolator(new android.view.animation.LinearInterpolator());animator.addUpdateListener(a->{time=(float)a.getAnimatedValue();invalidate();});animator.start();}
        @Override protected void onAttachedToWindow(){super.onAttachedToWindow();shown=isShown();motion();}
        @Override protected void onDetachedFromWindow(){if(animator!=null){animator.cancel();animator=null;}super.onDetachedFromWindow();}
        @Override public void onVisibilityAggregated(boolean visible){super.onVisibilityAggregated(visible);shown=visible;motion();}
        @Override protected void onDraw(Canvas canvas){float d=getResources().getDisplayMetrics().density,cx=getWidth()/2f,cy=getHeight()/2f;paint.setColor(WatchStyle.SURFACE);canvas.drawRoundRect(0,0,getWidth(),getHeight(),cy,cy,paint);for(int i=0;i<7;i++){float height=(active?8+16*(float)Math.abs(Math.sin(time+i*.65)):8+12*(1-Math.abs(i-3)/3f))*d;paint.setColor(phase.contains("Speaking")?WatchStyle.PEACH:WatchStyle.MINT);paint.setAlpha(active?230:130+(3-Math.abs(i-3))*30);float x=cx+(i-3)*9*d;canvas.drawRoundRect(x-2*d,cy-height/2,x+2*d,cy+height/2,2*d,2*d,paint);}paint.setAlpha(255);}
    }
}
